/* ===== carte_dati_en.js =====
   Le carte ruolo in INGLESE (J4, 05/09/2026): la STESSA arte nuda di
   carte_dati.js con nome, squadra e descrizione stampati in inglese da
   _scrivi_carte.py --en (cartella _scritte_en/), impacchettate da
   _impacchetta_carte.py con la stessa ricetta (LANCZOS, JPEG 384x576 q78;
   480x720 q80 per le quattro del 31/08). Stesse chiavi di CRT_B64, dorso
   identico. Le regole scritte sono quelle del motore (g_ruoli.js).

   Uso: quando la lingua e "en", g_ui usa CRT_B64_EN al posto di CRT_B64
   (crtURLEn ricade sull italiano se una chiave mancasse). Se questo
   pacchetto non e montato, la carta EN resta quella di prima: arte
   italiana con nome e descrizione in DOM (D-29). */
var CRT_B64_EN = {
    caposala: "",
    marcatore: "",
    direttore: "",
    cassiere: "",
    dorso: "",
    lupo: "",
    veggente: "",
    villico: "",
    guardiano: "",
    gemelli: "",
    dottore: "",
    medium: "",
    sciacallo: "",
    esattore: "",
    inquisitore: "",
    falsario: "",
    socio: ""
};

function crtURLEn(chiave) {
    var d = (typeof CRT_B64_EN !== "undefined" && CRT_B64_EN && CRT_B64_EN[chiave]) ?
            CRT_B64_EN[chiave] : null;
    if (!d && typeof CRT_B64 !== "undefined" && CRT_B64) {
        d = CRT_B64[chiave] || CRT_B64.villico;
    }
    return "data:image/jpeg;base64," + (d || "");
}
